fn sinf(a: i32) -> i32 {
    let tab = [0, 25, 49, 71, 90, 106, 117, 124, 127, 124, 117, 106, 90, 71, 49, 25, 0, -25, -49, -71, -90, -106, -117, -124, -127, -124, -117, -106, -90, -71, -49, -25];
    let i: i32 = (a >> 3) & 31;
    let f: i32 = a & 7;
    let s0: i32 = tab[i];
    let s1: i32 = tab[(i + 1) & 31];
    s0 + (s1 - s0) * f / 8
}

fn cosf(a: i32) -> i32 {
    sinf(a + 64)
}

fn isqrt(n: i32) -> i32 {
    if n <= 0 { return 0; }
    let mut x: i32 = n;
    let mut y: i32 = (x + 1) / 2;
    while y < x {
        x = y;
        y = (x + n / x) / 2;
    }
    x
}

fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    let cx: i32 = w / 2;
    let cy: i32 = h / 2;
    let pal = [0xffe08a, 0xffb347, 0xff7b54, 0xd64550];
    let mut n: i32 = t;
    if n > 300 { n = 300; }
    let rot: i32 = t / 6;
    host::display::clear(0x100805);
    let mut i: i32 = 0;
    while i < n {
        let a: i32 = i * 98 + rot;
        let r: i32 = isqrt(i * 176);
        let x: i32 = cx + cosf(a) * r / 127;
        let y: i32 = cy + sinf(a) * r / 127;
        let s: i32 = 2 + i / 60;
        host::display::fill_rect(x - s / 2, y - s / 2, s, s, pal[(i / 75) & 3]);
        i = i + 1;
    }
    host::display::present();
}
